#include "KS/SRC/ks/FEMenu_shared.h"

extern int getButtonState(int button, int controller);

struct GameState {
    char padding0[0xb0];
    int num_players;
    char padding1[0xc];
    int player_device[2];
};

struct Application {
    char padding[0x10];
    GameState *game;
};

struct BeachState {
    char padding[0x2d8];
    void *career;
};

extern Application *g_app;
extern BeachState *g_beach_ptr;
__asm__(".equ g_app, 0x0046AC18");
__asm__(".equ g_beach_ptr, 0x0043F710");
__asm__(".equ getButtonState__Fii, 0x00159270");

class PauseMenuSystem : public FEMenuSystem {
public:
    void InitAll();
};

void PauseMenuSystem::InitAll()
{
    device_flags = 1 << g_app->game->player_device[0];
    if (g_app->game->num_players >= 2)
        device_flags |= 1 << g_app->game->player_device[1];

    for (int i = 0; i < 14; i++)
        for (int j = 0; j < 2; j++)
            button_down[i][j] = getButtonState(i, j);

    for (int i = 0; i < count; i++)
        if (i != 15)
            menus[i]->Init();

    menus[16]->Load();
    if (g_beach_ptr->career)
        menus[17]->Load();
    menus[19]->Load();
    menus[21]->Load();
}
